import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { OrderService } from '../../services/order-service';
import { RouterLink } from '@angular/router';
import { Invoice, InvoiceItem } from '../../models/invoice';
import { InvoiceService } from '../../services/invoice-service';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import { party } from '../party/party';
import { PartyService } from '../../services/party-service';

export interface OrderDispatchList {
  id: number; // order id
  invoiceId: number; // invoice id
  invoiceNo: number; // invoiceNo from OrderDispatch
  customerName: string;
  customerPhone: number;
  customerEmail: string;
  orderDate: string;
}


@Component({
  selector: 'app-order-dispatch-list',
  imports: [FormsModule, CommonModule, RouterLink],
  templateUrl: './order-dispatch-list.html',
  styleUrl: './order-dispatch-list.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class OrderDispatchListComponent {
 order: OrderDispatchList[] = [];
 invoice: Invoice[] = [];
 parties: party[] = [];
  searchTerm = '';

  constructor(private userService: OrderService,  private cd: ChangeDetectorRef, private InvoiceService: InvoiceService, private PartyService: PartyService) {}

  ngOnInit() {
    this.userService.getOrdersByStatus(2).subscribe(data => {
  this.order = data.map(i => ({
    id: i.id,
    invoiceId: i.id,
    invoiceNo: i.invoiceNo,
    customerName: i.customerName,
    customerPhone: i.customerPhone,
    customerEmail: i.customerEmail,
    orderDate: i.orderDate
  }));
  this.cd.markForCheck();
});
    console.log("Users from backend:", this.order);

  // 2️⃣ Fetch Parties
this.PartyService.getParties().subscribe({
  next: (data) => {
    this.parties = data;
    console.log('Parties fetched:', this.parties);
  },
  error: (err) => {
    console.error('Failed to fetch parties:', err);
  }
});
  }
  

  filteredUsers() {
    const term = this.searchTerm.toLowerCase();
    return this.order.filter(u =>
      u.invoiceNo.toString().includes(term) ||
      u.customerName.toLowerCase().includes(term) ||
      u.customerPhone.toPrecision().includes(term) ||
      u.customerEmail.toLowerCase().includes(term) ||
      u.orderDate.toLowerCase().includes(term)
    );
  }
generateInvoice(invoiceId: number) {
  if (!invoiceId) return alert('Invalid Invoice ID.');

  // 1️⃣ Fetch invoice by ID
  this.InvoiceService.getInvoiceById(invoiceId).subscribe({
    next: (invoice: Invoice) => {
      // 2️⃣ Find party details
      const party = this.parties.find(p => p.id === invoice.partyId);

      // 3️⃣ Generate PDF
      const pdf = this.generateFullInvoicePdf(invoice, party);

      // 4️⃣ Open PDF in new tab
      const blobUrl = pdf.output('bloburl');
      window.open(blobUrl, '_blank');
    },
    error: (err) => {
      console.error('Failed to fetch invoice:', err);
      alert('Failed to fetch invoice data.');
    }
  });
}

// ------------------ FULL PDF GENERATOR ------------------
private generateFullInvoicePdf(invoice: Invoice, party?: party): jsPDF {
  const doc = new jsPDF('p', 'mm', 'a4');
  const pageWidth = doc.internal.pageSize.getWidth();
  const margin = 15;
  const tableWidth = pageWidth - margin * 2;
  let currentY = 20;

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(10);
  doc.setDrawColor(0);
  doc.setLineWidth(0.2);

  // OUTLINE
  doc.rect(margin, currentY, tableWidth, 240);

  // HEADER
  this.drawHeaderSection(doc, margin, currentY, tableWidth, invoice, party);
  currentY += 60;

  // ITEMS
  this.drawItemsHeader(doc, margin, currentY, tableWidth);
  currentY += 15;
  currentY = this.drawItemsData(doc, margin, currentY, tableWidth, invoice);

  // FOOTER
  this.drawFooterSection(doc, margin, currentY, tableWidth, invoice);

  return doc;
}

// ------------------ HEADER ------------------
private drawHeaderSection(doc: jsPDF, x: number, y: number, width: number, invoiceData: Invoice, party?: party) {
  const halfWidth = width / 2;
  doc.line(x + halfWidth, y, x + halfWidth, y + 60);

  // LEFT: Customer
  doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
  doc.text('Billed To:', x + 3, y + 8);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
  doc.text(`M/s. : ${party?.name || 'Customer Name'}`, x + 3, y + 16);

  const addressLines = this.splitText(party?.address || 'Customer Address', 45);
  let addressY = y + 24;
  doc.text('Address :', x + 3, addressY);
  addressLines.forEach((line, idx) => doc.text(line, x + 20, addressY + idx * 5));

  doc.text(`State: ${party?.state || 'STATE'}`, x + 3, y + 40);
  doc.text(`State Code: ${party?.stateCode || '00'}`, x + 60, y + 40);
  doc.text(`GSTIN : ${party?.gstin || 'N/A'}`, x + 3, y + 50);

  // RIGHT: Invoice Info
  const rightX = x + halfWidth + 3;
  doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
  doc.text('Invoice Details:', rightX, y + 8);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
  doc.text(`Invoice No.: ${invoiceData.id || 'N/A'}`, rightX, y + 16);
  doc.text(`Invoice Date: ${this.formatDate(invoiceData.invoiceDate)}`, rightX + 60, y + 16);
  doc.text(`Challan Date: ${(invoiceData.challanDate)}`, rightX + 60, y + 24);
  doc.text(`Place Of Supply: ${invoiceData.placeOfSupply || 'N/A'}`, rightX, y + 32);
  doc.text(`Transportation: ${invoiceData.transportation || 'N/A'}`, rightX, y + 40);
  doc.text(`Vehicle No.: ${invoiceData.vehicleNo || 'N/A'}`, rightX, y + 48);

  doc.line(x, y + 60, x + width, y + 60);
}

// ------------------ ITEMS HEADER ------------------
private drawItemsHeader(doc: jsPDF, x: number, y: number, width: number) {
  const colWidths = [15, 55, 25, 20, 25, 20, 25];
  let currentX = x;
  doc.setFont('helvetica', 'bold'); doc.setFontSize(9);

  colWidths.forEach((colWidth, idx) => {
    doc.line(currentX, y, currentX, y + 15);
    let text = ['', 'Description', '', '', '', '', ''][idx];
    switch (idx) {
      case 0: text = 'Item\nNo.'; break;
      case 2: text = 'HSN\nCode'; break;
      case 3: text = 'Qty.'; break;
      case 4: text = 'Rate'; break;
      case 5: text = 'Per'; break;
      case 6: text = 'Amount'; break;
    }
    if (text.includes('\n')) {
      const lines = text.split('\n');
      doc.text(lines[0], currentX + colWidth / 2, y + 6, { align: 'center' });
      doc.text(lines[1], currentX + colWidth / 2, y + 12, { align: 'center' });
    } else doc.text(text, currentX + colWidth / 2, y + 9, { align: 'center' });
    currentX += colWidth;
  });
  doc.line(currentX, y, currentX, y + 15);
  doc.line(x, y, x + width, y);
  doc.line(x, y + 15, x + width, y + 15);
}

// ------------------ ITEMS DATA ------------------
private drawItemsData(doc: jsPDF, x: number, y: number, width: number, invoiceData: Invoice): number {
  const colWidths = [15, 55, 25, 20, 25, 20, 25]; 
  const rowHeight = 12;
  let currentY = y; 
  doc.setFont('helvetica', 'normal'); 
  doc.setFontSize(9);

  invoiceData.items.forEach((item: InvoiceItem, idx: number) => {
    let currentX = x;
    colWidths.forEach(col => { doc.line(currentX, currentY, currentX + col, currentY + rowHeight); currentX += col; });
    currentX = x;
    doc.text((idx + 1).toString(), currentX + colWidths[0]/2, currentY + 8, { align: 'center' }); currentX += colWidths[0];
    doc.text(item.description || '', currentX + 2, currentY + 8); currentX += colWidths[1];
    doc.text(item.hsnCode || '', currentX + colWidths[2]/2, currentY + 8, { align: 'center' }); currentX += colWidths[2];
    doc.text((item.quantity || 0).toString(), currentX + colWidths[3]/2, currentY + 8, { align: 'center' }); currentX += colWidths[3];
    doc.text((item.rate || 0).toFixed(2), currentX + colWidths[4]/2, currentY + 8, { align: 'center' }); currentX += colWidths[4];
    doc.text(item.per ? `${item.per} Kg` : '1 Kg', currentX + colWidths[5]/2, currentY + 8, { align: 'center' }); currentX += colWidths[5];
    doc.text((item.amount || 0).toFixed(2), currentX + colWidths[6]/2, currentY + 8, { align: 'center' });
    currentY += rowHeight;
  });

  // Empty rows
  const totalItemRows = 8; 
  const emptyRows = totalItemRows - invoiceData.items.length;
  for (let i = 0; i < emptyRows; i++) {
    let currentX = x; colWidths.forEach(col => { doc.line(currentX, currentY, currentX + col, currentY + rowHeight); currentX += col; });
    currentY += rowHeight;
  }

  doc.line(x, currentY, x + width, currentY);
  return currentY;
}

// ------------------ FOOTER ------------------
private drawFooterSection(doc: jsPDF, x: number, y: number, width: number, invoiceData: Invoice) {
  const leftWidth = width * 0.6, rightWidth = width * 0.4;
  doc.line(x + leftWidth, y, x + leftWidth, y + 80);

  // Left: Bank/Terms
  let leftY = y + 10; doc.setFontSize(9);
  doc.text('GSTIN No.: 24AACFN7739D1ZD', x + 3, leftY); leftY += 6;
  doc.text('Bank Account No.: 75470500000035', x + 3, leftY); leftY += 6;
  doc.text('Bank Name: BANK OF BARODA', x + 3, leftY); leftY += 6;
  doc.text('Bank Branch: Odhav, Ahmedabad', x + 3, leftY); leftY += 6;
  doc.text('Bank IFSC Code: BARB0DBODHA', x + 3, leftY); leftY += 10;
  doc.text('Payment Terms .............. days', x + 3, leftY); leftY += 8;
  doc.text('RUPEES   Eighty Two Rupees Only', x + 3, leftY); leftY += 10;
  doc.text('Terms of Sales (Subject to Ahmedabad Jurisdiction)', x + 3, leftY); leftY += 6;

  // Right: Totals
  const rightX = x + leftWidth; this.drawTotalsTable(doc, rightX, y, rightWidth, invoiceData);
  doc.line(x, y + 80, x + width, y + 80);
}

// ------------------ TOTALS ------------------
private drawTotalsTable(doc: jsPDF, x: number, y: number, width: number, invoiceData: Invoice) {
  const rowHeight = 10; let currentY = y + 5; doc.setFontSize(9);

  const totalsData = [
    { label: 'Basic Amount', value: (invoiceData.basicAmount || 0).toFixed(2) },
    { label: `${invoiceData.discountPer || 0}% Discount`, value: (invoiceData.discountCash || 0).toFixed(2) },
    { label: 'Total Taxable Value', value: (invoiceData.discountedAmount || 0).toFixed(2) },
    { label: `IGST ${invoiceData.igstPer || 0} %`, value: (invoiceData.igstAmt || 0).toFixed(2) },
    { label: 'Round of Sale', value: (invoiceData.round || 0).toFixed(2) }
  ];

  totalsData.forEach(item => {
    doc.rect(x, currentY, width * 0.65, rowHeight);
    doc.rect(x + width * 0.65, currentY, width * 0.35, rowHeight);
    doc.text(item.label, x + 3, currentY + 7);
    doc.text(item.value, x + width - 5, currentY + 7, { align: 'right' });
    currentY += rowHeight;
  });

  // Total Amount
  doc.setFont('helvetica', 'bold');
  doc.rect(x, currentY, width * 0.65, rowHeight);
  doc.rect(x + width * 0.65, currentY, width * 0.35, rowHeight);
  doc.text('Total Amount After Tax', x + 3, currentY + 7);
  doc.text((invoiceData.grandTotal || 0).toFixed(2), x + width - 5, currentY + 7, { align: 'right' });

  // Signature
  currentY += rowHeight + 15;
  doc.setFont('helvetica', 'normal');
  doc.text('For, Navrang Chemical Industries', x + 3, currentY); currentY += 20;
  doc.text('Authorised Signature', x + 3, currentY);
}

// ------------------ HELPERS ------------------
private splitText(text: string, maxLength: number): string[] {
  if (!text) return [''];
  if (text.length <= maxLength) return [text];
  const words = text.split(' '); const lines: string[] = [];
  let line = '';
  words.forEach(w => { if ((line + w).length <= maxLength) line += (line ? ' ' : '') + w; else { lines.push(line); line = w; } });
  if (line) lines.push(line);
  return lines;
}

private formatDate(date: string | Date): string {
  if (!date) return '';
  const d = typeof date === 'string' ? new Date(date) : date;
  return d.toLocaleDateString('en-IN', { day: '2-digit', month: '2-digit', year: 'numeric' });
}


}